describe('Form Auto-Save Draft Feature', () => {
  const AUTOSAVE_INTERVAL = 30000;
  const FORM_SELECTOR = 'form[data-testid="draft-form"]';
  const INPUT_FIELD = 'input[name="title"]';
  const TEXTAREA_FIELD = 'textarea[name="content"]';
  const DRAFT_INDICATOR = '[data-testid="draft-saved-indicator"]';
  const LAST_SAVED_TIME = '[data-testid="last-saved-time"]';

  beforeEach(() => {
    cy.visit('/form');
    cy.get(FORM_SELECTOR).should('be.visible');
  });

  it('should auto-save form data as draft every 30 seconds', () => {
    const testTitle = 'Test Draft Title';
    const testContent = 'This is test content for auto-save';

    cy.get(INPUT_FIELD).type(testTitle);
    cy.get(TEXTAREA_FIELD).type(testContent);

    // Verify initial state - no save yet
    cy.get(DRAFT_INDICATOR).should('not.exist');

    // Wait for first auto-save (30 seconds)
    cy.get(DRAFT_INDICATOR, { timeout: AUTOSAVE_INTERVAL + 5000 })
      .should('be.visible')
      .and('contain', 'Draft saved');

    // Verify last saved time is updated
    cy.get(LAST_SAVED_TIME).should('not.be.empty');

    // Verify data persists in localStorage
    cy.window().then((win) => {
      const savedDraft = JSON.parse(win.localStorage.getItem('formDraft'));
      expect(savedDraft.title).to.equal(testTitle);
      expect(savedDraft.content).to.equal(testContent);
    });

    // Wait for second auto-save cycle
    cy.get(DRAFT_INDICATOR).then(($el) => {
      const firstSaveTime = $el.attr('data-timestamp');

      cy.wait(AUTOSAVE_INTERVAL + 2000);
      cy.get(DRAFT_INDICATOR).should(($el2) => {
        const secondSaveTime = $el2.attr('data-timestamp');
        expect(parseInt(secondSaveTime)).to.be.greaterThan(parseInt(firstSaveTime));
      });
    });
  });

  it('should handle form changes and save updated draft content', () => {
    const initialTitle = 'Initial Title';
    const updatedTitle = 'Updated Title';
    const initialContent = 'Initial content';
    const updatedContent = 'Updated content with more details';

    // Fill initial form data
    cy.get(INPUT_FIELD).type(initialTitle);
    cy.get(TEXTAREA_FIELD).type(initialContent);

    // Wait for first auto-save
    cy.get(DRAFT_INDICATOR, { timeout: AUTOSAVE_INTERVAL + 5000 })
      .should('be.visible');

    // Verify initial draft saved
    cy.window().then((win) => {
      const savedDraft = JSON.parse(win.localStorage.getItem('formDraft'));
      expect(savedDraft.title).to.equal(initialTitle);
    });

    // Update form fields
    cy.get(INPUT_FIELD).clear().type(updatedTitle);
    cy.get(TEXTAREA_FIELD).clear().type(updatedContent);

    // Wait for next auto-save cycle
    cy.wait(AUTOSAVE_INTERVAL + 2000);

    // Verify updated draft is saved
    cy.window().then((win) => {
      const updatedDraft = JSON.parse(win.localStorage.getItem('formDraft'));
      expect(updatedDraft.title).to.equal(updatedTitle);
      expect(updatedDraft.content).to.equal(updatedContent);
    });

    // Verify draft indicator shows recent save
    cy.get(DRAFT_INDICATOR).should('contain', 'Draft saved');
  });

  it('should not save empty or invalid form data as draft', () => {
    // Leave form empty and wait for auto-save interval
    cy.wait(AUTOSAVE_INTERVAL + 2000);

    // Verify no draft was saved for empty form
    cy.window().then((win) => {
      const savedDraft = win.localStorage.getItem('formDraft');
      expect(savedDraft).to.be.null;
    });

    // Verify no save indicator appears
    cy.get(DRAFT_INDICATOR).should('not.exist');
  });

  it('should continue auto-saving even when user is idle', () => {
    const testData = 'Test data for idle state';

    cy.get(INPUT_FIELD).type(testData);

    // Wait for first auto-save
    cy.get(DRAFT_INDICATOR, { timeout: AUTOSAVE_INTERVAL + 5000 })
      .should('be.visible');

    // Simulate user inactivity - no interactions for 60+ seconds
    cy.wait(AUTOSAVE_INTERVAL + 2000);

    // Verify second auto-save occurred without user interaction
    cy.get(DRAFT_INDICATOR).should('be.visible');

    cy.window().then((win) => {
      const savedDraft = JSON.parse(win.localStorage.getItem('formDraft'));
      expect(savedDraft.title).to.equal(testData);
    });
  });

  it('should recover draft data on page reload', () => {
    const draftTitle = 'Draft to Recover';
    const draftContent = 'Content that should persist';

    cy.get(INPUT_FIELD).type(draftTitle);
    cy.get(TEXTAREA_FIELD).type(draftContent);

    // Wait for auto-save
    cy.get(DRAFT_INDICATOR, { timeout: AUTOSAVE_INTERVAL + 5000 })
      .should('be.visible');

    // Reload page
    cy.reload();

    // Verify form is populated with saved draft
    cy.get(INPUT_FIELD).should('have.value', draftTitle);
    cy.get(TEXTAREA_FIELD).should('have.value', draftContent);

    // Verify draft indicator shows recovery
    cy.get(DRAFT_INDICATOR).should('contain', 'Draft recovered');
  });

  it('should clear draft after successful form submission', () => {
    const submitButton = 'button[type="submit"]';
    const successMessage = '[data-testid="success-message"]';

    cy.get(INPUT_FIELD).type('Final submission');
    cy.get(TEXTAREA_FIELD).type('Final content');

    // Wait for auto-save
    cy.get(DRAFT_INDICATOR, { timeout: AUTOSAVE_INTERVAL + 5000 })
      .should('be.visible');

    // Submit form
    cy.get(submitButton).click();

    // Verify success
    cy.get(successMessage).should('be.visible');

    // Verify draft is cleared from localStorage
    cy.window().then((win) => {
      const savedDraft = win.localStorage.getItem('formDraft');
      expect(savedDraft).to.be.null;
    });

    // Verify draft indicator is removed
    cy.get(DRAFT_INDICATOR).should('not.exist');
  });
});
